class Record:
    """Simple record storing ordered keys and values."""

    def __init__(self, **kwargs):
        self._keys = list(kwargs.keys())
        self._data = list(kwargs.values())

    def data(self, *keys):
        """
        Return the keys and values of this record as a dictionary,
        optionally including only certain values by index or key. Keys
        provided that are not in the record will be inserted with a value
        of None; indexes provided that are out of bounds will trigger
        an IndexError.
        """
        if not keys:
            return dict(zip(self._keys, self._data))

        result = {}
        for key in keys:
            if isinstance(key, int):
                if key < 0 or key >= len(self._data):
                    raise IndexError(f"Index {key} out of bounds")
                result[self._keys[key]] = self._data[key]
            else:
                if key in self._keys:
                    idx = self._keys.index(key)
                    result[key] = self._data[idx]
                else:
                    result[key] = None
        return result
```

